<?php
require_once __DIR__ . '/connection.php';
session_start();
if (!isset($_SESSION['user_id'])) { header('Location: login.php'); exit; }
if ((int) ($_SESSION['type'] ?? 0) !== 1 && empty($_SESSION['admin_logged_in'])) { http_response_code(403); die('Admin access required.'); }

$userId = filter_input(INPUT_GET, 'user_id', FILTER_VALIDATE_INT);
if (!$userId) { http_response_code(400); die('Invalid station user.'); }
$stationStmt = $conn->prepare('SELECT u.user_id, u.station_id, s.station_name, u.organisation_name FROM OBHS_users u INNER JOIN OBHS_station s ON s.station_id = u.station_id WHERE u.user_id = ? AND u.type = 2 LIMIT 1');
$stationStmt->bind_param('i', $userId); $stationStmt->execute(); $station = $stationStmt->get_result()->fetch_assoc(); $stationStmt->close();
if (!$station) { http_response_code(404); die('Station not found.'); }

if (empty($_SESSION['data_delete_csrf'])) { $_SESSION['data_delete_csrf'] = bin2hex(random_bytes(32)); }
$deleteResult = $_SESSION['data_delete_result'] ?? null; unset($_SESSION['data_delete_result']);

$filters = [
  'from_date' => preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from_date']??''))?(string)$_GET['from_date']:'',
  'to_date' => preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to_date']??''))?(string)$_GET['to_date']:'',
  'train_no' => substr(trim((string)($_GET['train_no']??'')),0,100), 'grade' => substr(trim((string)($_GET['grade']??'')),0,100),
  'coach_no' => substr(trim((string)($_GET['coach_no']??'')),0,100), 'employee_id' => substr(trim((string)($_GET['employee_id']??'')),0,100),
  'attendance_type' => substr(trim((string)($_GET['attendance_type']??'')),0,100),
  'verified' => in_array((string)($_GET['verified']??''),['0','1'],true)?(string)$_GET['verified']:'',
  'cleaning_area' => substr(trim((string)($_GET['cleaning_area']??'')),0,100),
];

function previewWhere(mysqli $conn,string $stationId,string $scope,array $f):string {
  $w="station_id='".$conn->real_escape_string($stationId)."'";
  if($f['from_date']!=='')$w.=" AND created_at>='".$conn->real_escape_string($f['from_date'])." 00:00:00'";
  if($f['to_date']!=='')$w.=" AND created_at<DATE_ADD('".$conn->real_escape_string($f['to_date'])."',INTERVAL 1 DAY)";
  if($f['train_no']!=='')$w.=" AND train_no='".$conn->real_escape_string($f['train_no'])."'";
  if($f['grade']!=='')$w.=" AND grade='".$conn->real_escape_string($f['grade'])."'";
  if($scope==='feedback'){if($f['coach_no']!=='')$w.=" AND coach_no='".$conn->real_escape_string($f['coach_no'])."'";if($f['verified']!=='')$w.=' AND verified='.(int)$f['verified'];}
  if($scope==='attendance'){if($f['employee_id']!=='')$w.=" AND employee_id='".$conn->real_escape_string($f['employee_id'])."'";if($f['attendance_type']!=='')$w.=" AND type_of_attendance='".$conn->real_escape_string($f['attendance_type'])."'";}
  if($scope==='photo_report'){if($f['coach_no']!=='')$w.=" AND coach_no='".$conn->real_escape_string($f['coach_no'])."'";if($f['cleaning_area']!=='')$w.=" AND cleaning_area='".$conn->real_escape_string($f['cleaning_area'])."'";}
  return $w;
}
function oneCount(mysqli $conn,string $table,string $where):int{$r=$conn->query("SELECT COUNT(*) total FROM `{$table}` WHERE {$where}");return $r?(int)$r->fetch_assoc()['total']:0;}
function previewRows(mysqli $conn,string $sql):array{$rows=[];$r=$conn->query($sql);if($r)while($row=$r->fetch_assoc())$rows[]=$row;return $rows;}

$stationId=(string)$station['station_id'];
$whereFeedback=previewWhere($conn,$stationId,'feedback',$filters); $whereAttendance=previewWhere($conn,$stationId,'attendance',$filters); $wherePhoto=previewWhere($conn,$stationId,'photo_report',$filters);
$counts=['feedback'=>oneCount($conn,'OBHS_passenger',$whereFeedback),'attendance'=>oneCount($conn,'base_attendance',$whereAttendance),'photo_report'=>oneCount($conn,'base_photo_report',$wherePhoto)];
$total=array_sum($counts); $hasFilter=count(array_filter($filters,static fn($v)=>$v!==''))>0;
$feedbackPreview=previewRows($conn,"SELECT unique_id id,name,train_no,coach_no,grade,verified,created_at FROM OBHS_passenger WHERE {$whereFeedback} ORDER BY created_at DESC LIMIT 5");
$attendancePreview=previewRows($conn,"SELECT id,employee_id,employee_name,train_no,grade,type_of_attendance,created_at FROM base_attendance WHERE {$whereAttendance} ORDER BY created_at DESC LIMIT 5");
$photoPreview=previewRows($conn,"SELECT id,train_no,coach_no,grade,cleaning_area,janitor,created_at FROM base_photo_report WHERE {$wherePhoto} ORDER BY created_at DESC LIMIT 5");
?>
