<script>document.addEventListener('DOMContentLoaded',function(){const scopes=[...document.querySelectorAll('.data-scope')],text=document.getElementById('deleteDataText'),confirmBox=document.getElementById('confirmDataDelete'),allBox=document.getElementById('confirmAll'),button=document.getElementById('deleteDataButton'),countText=document.getElementById('selectedDeleteCount'),buttonCount=document.getElementById('deleteDataButtonCount');const update=()=>{const count=scopes.filter(x=>x.checked).reduce((n,x)=>n+Number(x.dataset.count||0),0),hasScope=scopes.some(x=>x.checked),allOk=!allBox||allBox.checked;countText.textContent=count.toLocaleString();buttonCount.textContent=count.toLocaleString();button.disabled=!(count>0&&hasScope&&text.value==='DELETE DATA'&&confirmBox.checked&&allOk)};scopes.forEach(x=>x.addEventListener('change',update));text.addEventListener('input',update);confirmBox.addEventListener('change',update);if(allBox)allBox.addEventListener('change',update);document.getElementById('deleteDataForm').addEventListener('submit',e=>{const count=scopes.filter(x=>x.checked).reduce((n,x)=>n+Number(x.dataset.count||0),0);if(!confirm('Permanently delete '+count.toLocaleString()+' database records and associated images?'))e.preventDefault()});const s=document.querySelector('.sidebar-wrapper');if(s&&window.OverlayScrollbarsGlobal?.OverlayScrollbars)OverlayScrollbarsGlobal.OverlayScrollbars(s,{scrollbars:{theme:'os-theme-light',autoHide:'leave',clickScroll:true}});update()});</script></body></html>
